create table if not exists public.exam_subject_configs (id uuid primary key default gen_random_uuid(), exam_code text not null, subject_title text not null, position int not null default 0, is_active boolean not null default true, created_at timestamptz not null default now(), unique (exam_code, subject_title));
insert into public.exam_subject_configs (exam_code, subject_title, position) values ('IFOM_CSE','Dermatology',10),('IFOM_CSE','Infectious Diseases',20),('IFOM_CSE','Respiratory System',30),('IFOM_CSE','Renal & Urogenital',40),('IFOM_CSE','Rheumatology & Orthopedics',50),('IFOM_CSE','Hematology',60),('IFOM_CSE','Endocrine',70),('IFOM_CSE','Cardiology',80),('IFOM_CSE','Neurology',90),('IFOM_CSE','Obstetrics & Gynecology',100),('IFOM_CSE','Pediatrics',110),('IFOM_CSE','Psychiatry',120),('IFOM_CSE','Biostatistics',130) on conflict (exam_code, subject_title) do nothing;
create table if not exists public.source_documents (id uuid primary key default gen_random_uuid(), lesson_id uuid references public.lessons(id) on delete set null, title text not null, exam_code text not null default 'IFOM_CSE', subject_title text, topic_title text, source_kind text not null default 'lesson', status text not null default 'queued', extracted_text text, chunk_count int not null default 0, meta jsonb not null default '{}'::jsonb, created_by uuid references public.profiles(id), created_at timestamptz not null default now(), processed_at timestamptz);
create table if not exists public.document_chunks (id uuid primary key default gen_random_uuid(), source_document_id uuid not null references public.source_documents(id) on delete cascade, chunk_index int not null, content text not null, content_hash text not null, created_at timestamptz not null default now(), unique (source_document_id, chunk_index), unique (source_document_id, content_hash));
create table if not exists public.chunk_embeddings (id uuid primary key default gen_random_uuid(), document_chunk_id uuid not null references public.document_chunks(id) on delete cascade, embedding vector(1536), embedding_model text not null default 'local-1536', created_at timestamptz not null default now(), unique (document_chunk_id));
create index if not exists chunk_embeddings_vector_idx on public.chunk_embeddings using ivfflat (embedding vector_cosine_ops) with (lists = 100);
create table if not exists public.medical_concepts (id uuid primary key default gen_random_uuid(), source_document_id uuid not null references public.source_documents(id) on delete cascade, concept text not null, concept_type text not null default 'topic', weight numeric not null default 1, created_at timestamptz not null default now());
create table if not exists public.generated_questions (id uuid primary key default gen_random_uuid(), question_id uuid references public.questions(id) on delete set null, source_document_id uuid references public.source_documents(id) on delete set null, exam_code text not null default 'IFOM_CSE', subject_title text, topic_title text, generation_engine text not null default 'internal-rag', meta jsonb not null default '{}'::jsonb, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table if not exists public.question_evidence (id uuid primary key default gen_random_uuid(), question_id uuid not null references public.questions(id) on delete cascade, source_document_id uuid references public.source_documents(id) on delete set null, evidence_text text not null, start_char int, end_char int, confidence numeric, created_at timestamptz not null default now());
create table if not exists public.generated_flashcards (id uuid primary key default gen_random_uuid(), flashcard_id uuid references public.flashcards(id) on delete set null, source_document_id uuid references public.source_documents(id) on delete set null, exam_code text not null default 'IFOM_CSE', subject_title text, topic_title text, generation_engine text not null default 'internal-rag', meta jsonb not null default '{}'::jsonb, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table if not exists public.quiz_sessions_ext (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, mode text not null, exam_code text not null default 'IFOM_CSE', subject_title text, topic_title text, question_count int not null default 20, meta jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.rag_query_logs (id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id) on delete set null, question text not null, mode text not null default 'tutor', citations_count int not null default 0, answer_preview text, meta jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
alter table public.exam_subject_configs enable row level security; alter table public.source_documents enable row level security; alter table public.document_chunks enable row level security; alter table public.chunk_embeddings enable row level security; alter table public.medical_concepts enable row level security; alter table public.generated_questions enable row level security; alter table public.question_evidence enable row level security; alter table public.generated_flashcards enable row level security; alter table public.quiz_sessions_ext enable row level security; alter table public.rag_query_logs enable row level security;
drop policy if exists "exam configs read" on public.exam_subject_configs; create policy "exam configs read" on public.exam_subject_configs for select using (public.is_active() or public.is_admin());
drop policy if exists "exam configs write" on public.exam_subject_configs; create policy "exam configs write" on public.exam_subject_configs for all using (public.is_admin()) with check (public.is_admin());
drop policy if exists "source docs read" on public.source_documents; create policy "source docs read" on public.source_documents for select using (public.is_active() or public.is_admin());
drop policy if exists "source docs write" on public.source_documents; create policy "source docs write" on public.source_documents for all using (public.is_admin()) with check (public.is_admin());
drop policy if exists "doc chunks read" on public.document_chunks; create policy "doc chunks read" on public.document_chunks for select using (public.is_active() or public.is_admin());
drop policy if exists "doc chunks write" on public.document_chunks; create policy "doc chunks write" on public.document_chunks for all using (public.is_admin()) with check (public.is_admin());
drop policy if exists "chunk embeddings read" on public.chunk_embeddings; create policy "chunk embeddings read" on public.chunk_embeddings for select using (public.is_active() or public.is_admin());
drop policy if exists "chunk embeddings write" on public.chunk_embeddings; create policy "chunk embeddings write" on public.chunk_embeddings for all using (public.is_admin()) with check (public.is_admin());
drop policy if exists "concepts read" on public.medical_concepts; create policy "concepts read" on public.medical_concepts for select using (public.is_active() or public.is_admin());
drop policy if exists "concepts write" on public.medical_concepts; create policy "concepts write" on public.medical_concepts for all using (public.is_admin()) with check (public.is_admin());
drop policy if exists "generated questions read" on public.generated_questions; create policy "generated questions read" on public.generated_questions for select using (public.is_active() or public.is_admin());
drop policy if exists "generated questions write" on public.generated_questions; create policy "generated questions write" on public.generated_questions for all using (public.is_admin()) with check (public.is_admin());
drop policy if exists "question evidence read" on public.question_evidence; create policy "question evidence read" on public.question_evidence for select using (public.is_active() or public.is_admin());
drop policy if exists "question evidence write" on public.question_evidence; create policy "question evidence write" on public.question_evidence for all using (public.is_admin()) with check (public.is_admin());
drop policy if exists "generated flashcards read" on public.generated_flashcards; create policy "generated flashcards read" on public.generated_flashcards for select using (public.is_active() or public.is_admin());
drop policy if exists "generated flashcards write" on public.generated_flashcards; create policy "generated flashcards write" on public.generated_flashcards for all using (public.is_admin()) with check (public.is_admin());
drop policy if exists "quiz ext self" on public.quiz_sessions_ext; create policy "quiz ext self" on public.quiz_sessions_ext for all using (user_id = auth.uid() or public.is_admin()) with check (user_id = auth.uid() or public.is_admin());
drop policy if exists "rag logs self" on public.rag_query_logs; create policy "rag logs self" on public.rag_query_logs for all using (user_id = auth.uid() or public.is_admin()) with check (user_id = auth.uid() or public.is_admin());
